import ArgumentParser

/// Escapes one shell completion candidate (a list name) for the shell that asked for it.
///
/// Each completion script generated by ArgumentParser reads the candidates differently:
/// - zsh passes them to `_describe`, which splits `name:description` at an unescaped `:` and
///   removes the other backslashes, so `\` and `:` are escaped. zsh quotes the rest itself.
/// - bash passes them to `compgen -W`, which expands every word (`$VAR`, `$(...)`, backticks,
///   braces) and removes quotes. Escaping every ASCII character other than letters, digits and
///   `-_./` makes that expansion return the name unchanged instead of running any of it.
/// - fish takes every line literally and quotes it itself, so the name is left as it is.
func escapeCompletionCandidate(_ name: String, for shell: CompletionShell?) -> String {
    switch shell {
    case CompletionShell.zsh:
        return name
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: ":", with: "\\:")
    case CompletionShell.bash:
        return String(name.flatMap { needsBashEscape($0) ? ["\\", $0] : [$0] })
    default:
        return name
    }
}

private func needsBashEscape(_ character: Character) -> Bool {
    guard character.isASCII else {
        return false
    }
    return !(character.isLetter || character.isNumber || "-_./".contains(character))
}
